IF OBJECT_ID('dbo.Users','U') IS NULL
CREATE TABLE Users(
 Id INT IDENTITY(1,1) PRIMARY KEY,
 UserId AS Id PERSISTED,
 FullName NVARCHAR(100) NOT NULL, Username NVARCHAR(50) NOT NULL UNIQUE,
 Email NVARCHAR(120) NOT NULL, PasswordHash NVARCHAR(200) NOT NULL,
 Role NVARCHAR(20) NOT NULL CHECK(Role IN('Admin','Organizer','Student','Faculty')),
 Phone NVARCHAR(30) NULL, Department NVARCHAR(100) NULL, IsActive BIT NOT NULL DEFAULT 1
);
IF OBJECT_ID('dbo.Categories','U') IS NULL CREATE TABLE Categories(Id INT IDENTITY PRIMARY KEY,CategoryName NVARCHAR(100) NOT NULL,Description NVARCHAR(500) NULL);
IF OBJECT_ID('dbo.Venues','U') IS NULL CREATE TABLE Venues(Id INT IDENTITY PRIMARY KEY,VenueName NVARCHAR(100) NOT NULL,Location NVARCHAR(150) NULL,Capacity NVARCHAR(30) NULL,IsAvailable NVARCHAR(10) NULL);
IF OBJECT_ID('dbo.Notices','U') IS NULL CREATE TABLE Notices(Id INT IDENTITY PRIMARY KEY,Title NVARCHAR(150) NOT NULL,Body NVARCHAR(1000) NULL);
IF OBJECT_ID('dbo.Events','U') IS NULL CREATE TABLE Events(Id INT IDENTITY PRIMARY KEY,OwnerUserId INT NOT NULL,Title NVARCHAR(150),Description NVARCHAR(1000),Category NVARCHAR(100),Venue NVARCHAR(150),EventDate NVARCHAR(50),Capacity NVARCHAR(30),Status NVARCHAR(30));
IF OBJECT_ID('dbo.Schedules','U') IS NULL CREATE TABLE Schedules(Id INT IDENTITY PRIMARY KEY,OwnerUserId INT NOT NULL,EventTitle NVARCHAR(150),SessionTitle NVARCHAR(150),StartTime NVARCHAR(50),EndTime NVARCHAR(50),Room NVARCHAR(100));
IF OBJECT_ID('dbo.Speakers','U') IS NULL CREATE TABLE Speakers(Id INT IDENTITY PRIMARY KEY,OwnerUserId INT NOT NULL,EventTitle NVARCHAR(150),SpeakerName NVARCHAR(150),Email NVARCHAR(120),Topic NVARCHAR(200));
IF OBJECT_ID('dbo.Sponsors','U') IS NULL CREATE TABLE Sponsors(Id INT IDENTITY PRIMARY KEY,OwnerUserId INT NOT NULL,EventTitle NVARCHAR(150),SponsorName NVARCHAR(150),ContactEmail NVARCHAR(120),Contribution NVARCHAR(100));
IF OBJECT_ID('dbo.Registrations','U') IS NULL CREATE TABLE Registrations(Id INT IDENTITY PRIMARY KEY,OwnerUserId INT NOT NULL,EventTitle NVARCHAR(150),StudentName NVARCHAR(150),StudentEmail NVARCHAR(120),RegistrationStatus NVARCHAR(30));
IF OBJECT_ID('dbo.Feedback','U') IS NULL CREATE TABLE Feedback(Id INT IDENTITY PRIMARY KEY,OwnerUserId INT NOT NULL,EventTitle NVARCHAR(150),Rating NVARCHAR(10),Comment NVARCHAR(1000));
IF OBJECT_ID('dbo.Favourites','U') IS NULL CREATE TABLE Favourites(Id INT IDENTITY PRIMARY KEY,OwnerUserId INT NOT NULL,EventTitle NVARCHAR(150),Note NVARCHAR(500));
IF OBJECT_ID('dbo.Participations','U') IS NULL CREATE TABLE Participations(Id INT IDENTITY PRIMARY KEY,OwnerUserId INT NOT NULL,EventTitle NVARCHAR(150),AttendanceStatus NVARCHAR(30),CertificateStatus NVARCHAR(30));
IF OBJECT_ID('dbo.Approvals','U') IS NULL CREATE TABLE Approvals(Id INT IDENTITY PRIMARY KEY,OwnerUserId INT NOT NULL,EventTitle NVARCHAR(150),OrganizerName NVARCHAR(150),Decision NVARCHAR(30),Remarks NVARCHAR(1000));
IF OBJECT_ID('dbo.DepartmentEvents','U') IS NULL CREATE TABLE DepartmentEvents(Id INT IDENTITY PRIMARY KEY,OwnerUserId INT NOT NULL,Department NVARCHAR(100),EventTitle NVARCHAR(150),EventDate NVARCHAR(50),Coordinator NVARCHAR(150));
IF OBJECT_ID('dbo.Resources','U') IS NULL CREATE TABLE Resources(Id INT IDENTITY PRIMARY KEY,OwnerUserId INT NOT NULL,EventTitle NVARCHAR(150),ResourceName NVARCHAR(150),Quantity NVARCHAR(30),ResourceStatus NVARCHAR(30));
IF OBJECT_ID('dbo.Evaluations','U') IS NULL CREATE TABLE Evaluations(Id INT IDENTITY PRIMARY KEY,OwnerUserId INT NOT NULL,EventTitle NVARCHAR(150),EvaluationScore NVARCHAR(20),Strengths NVARCHAR(1000),Improvements NVARCHAR(1000));
